// Sync: caller blocks and fails if 'billing' is down.
func placeOrderSync(billing BillingClient, o Order) error {
	return billing.Charge(o) // blocks; downstream outage = upstream error
}

// Async: publish an event and return; billing consumes later.
func placeOrderAsync(w *kafka.Writer, o Order) error {
	payload, _ := json.Marshal(o)
	// The order is durable in Kafka even if billing is offline right now.
	return w.WriteMessages(context.Background(), kafka.Message{
		Key:   []byte(o.ID), // key -> partition, preserves per-order ordering
		Value: payload,
	})
}

