import (
	"context"

	"github.com/segmentio/kafka-go"
)

func produce(ctx context.Context) error {
	w := &kafka.Writer{
		Addr:     kafka.TCP("localhost:9092"),
		Topic:    "orders",
		Balancer: &kafka.Hash{}, // hash Key -> partition (per-key ordering)
	}
	defer w.Close()
	// Same Key always maps to the same partition, preserving offset order.
	return w.WriteMessages(ctx,
		kafka.Message{Key: []byte("order-1"), Value: []byte(`{"n":1}`)},
		kafka.Message{Key: []byte("order-1"), Value: []byte(`{"n":2}`)},
	)
}

