func consume(ctx context.Context) error {
	r := kafka.NewReader(kafka.ReaderConfig{
		Brokers: []string{"localhost:9092"},
		GroupID: "order-workers", // group => partitions split across members
		Topic:   "orders",
	})
	defer r.Close()
	for {
		m, err := r.ReadMessage(ctx) // auto-joins group, gets assigned partitions
		if err != nil {
			return err
		}
		// Records from one partition arrive in offset order.
		fmt.Printf("p%d off%d key=%s\n", m.Partition, m.Offset, m.Key)
	}
}

