import "sync"

// A tiny idempotency guard keyed by event ID.
type dedupe struct {
	mu   sync.Mutex
	seen map[string]struct{}
}

// process returns true only the FIRST time an event ID is seen.
func (d *dedupe) process(eventID string, apply func()) bool {
	d.mu.Lock()
	defer d.mu.Unlock()
	if _, ok := d.seen[eventID]; ok {
		return false // duplicate under at-least-once: skip side effects
	}
	d.seen[eventID] = struct{}{}
	apply() // in production this is a DB upsert keyed by eventID
	return true
}

