import (
	"fmt"

	"github.com/nats-io/nats.go"
)

func jetstream() error {
	nc, err := nats.Connect(nats.DefaultURL)
	if err != nil {
		return err
	}
	defer nc.Close()
	js, _ := nc.JetStream()
	// Durable stream persists messages for replay & redelivery.
	js.AddStream(&nats.StreamConfig{Name: "ORDERS", Subjects: []string{"orders.*"}})
	js.Publish("orders.created", []byte(`{"id":"o1"}`))

	// Explicit ack: unacked msgs are redelivered (at-least-once).
	sub, _ := js.PullSubscribe("orders.created", "workers")
	msgs, _ := sub.Fetch(1)
	for _, m := range msgs {
		fmt.Printf("got %s\n", m.Data)
		m.Ack() // ack only after successful processing
	}
	return nil
}

