	for range time.Tick(10 * time.Second) {
		// Reader.Stats().Lag = messages behind the newest offset.
		lag := r.Stats().Lag
		if lag > 10_000 {
			log.Printf("WARN consumer lag=%d: scale out or speed up", lag)
		}
	}
}

