package main

import (
	"context"
	"encoding/json"
	"log"

	"github.com/segmentio/kafka-go"
)

type event struct {
	ID string `json:"id"`
}

func main() {
	r := kafka.NewReader(kafka.ReaderConfig{
		Brokers: []string{"localhost:9092"},
		GroupID: "order-workers",
		Topic:   "orders",
	})
	defer r.Close()

	seen := map[string]struct{}{}
	ctx := context.Background()
	for {
		m, err := r.FetchMessage(ctx) // FetchMessage does NOT auto-commit
		if err != nil {
			log.Fatal(err)
		}
		var e event
		if err := json.Unmarshal(m.Value, &e); err != nil {
			log.Printf("bad payload off=%d: %v", m.Offset, err)
			_ = r.CommitMessages(ctx, m) // poison message: skip, don't loop forever
			continue
		}
		if _, dup := seen[e.ID]; !dup {
			seen[e.ID] = struct{}{}
			log.Printf("processed %s (off=%d)", e.ID, m.Offset)
		}
		_ = r.CommitMessages(ctx, m) // commit AFTER processing
	}
}

