package main

import (
	"fmt"
	"time"

	"github.com/nats-io/nats.go"
)

func main() {
	nc, err := nats.Connect(nats.DefaultURL)
	if err != nil {
		panic(err)
	}
	defer nc.Close()

	// Responder: any listener on the subject can reply.
	nc.Subscribe("time.now", func(m *nats.Msg) {
		m.Respond([]byte(time.Now().Format(time.RFC3339)))
	})

	// Requester: blocks up to the timeout for exactly one reply.
	resp, err := nc.Request("time.now", nil, time.Second)
	if err != nil {
		panic(err) // nats.ErrTimeout if no responder answered in time
	}
	fmt.Printf("reply: %s\n", resp.Data)
}

package main

import (
	"log"
	"time"

	"github.com/nats-io/nats.go"
)

func main() {
	nc, _ := nats.Connect(nats.DefaultURL)
	defer nc.Close()
	js, _ := nc.JetStream()

	// Durable stream + explicit-ack consumer.
	js.AddStream(&nats.StreamConfig{Name: "ORDERS", Subjects: []string{"orders.*"}})
	js.Publish("orders.created", []byte(`{"id":"o1"}`))

	sub, _ := js.PullSubscribe("orders.created", "order-workers",
		nats.AckWait(30*time.Second)) // unacked after 30s => redelivered
	defer sub.Unsubscribe()

	msgs, err := sub.Fetch(10, nats.MaxWait(2*time.Second))
	if err != nil && err != nats.ErrTimeout {
		log.Fatal(err)
	}
	for _, m := range msgs {
		if err := handle(m.Data); err != nil {
			m.Nak() // negative ack -> redeliver soon
			continue
		}
		m.Ack() // ack ONLY after success; commits progress
	}
}

func handle(b []byte) error {
	log.Printf("handling %s", b)
	return nil
}

