package solution

import "sync"

// IdempotentStore ensures each event ID is applied at most once.
type IdempotentStore struct {
	mu   sync.Mutex
	done map[string]struct{}
}

func NewIdempotentStore() *IdempotentStore {
	return &IdempotentStore{done: make(map[string]struct{})}
}

// Handle runs apply at most once per eventID.
func (s *IdempotentStore) Handle(eventID string, apply func() error) error {
	s.mu.Lock()
	if _, ok := s.done[eventID]; ok {
		s.mu.Unlock()
		return nil // duplicate: already applied, no side effect
	}
	s.mu.Unlock()

	if err := apply(); err != nil {
		return err // do NOT record on failure so retry can run
	}

	s.mu.Lock()
	s.done[eventID] = struct{}{} // record only after success
	s.mu.Unlock()
	return nil
}

