package solution

import (
	"errors"
	"testing"
)

func TestIdempotent(t *testing.T) {
	s := NewIdempotentStore()
	calls := 0
	apply := func() error { calls++; return nil }

	_ = s.Handle("e1", apply)
	_ = s.Handle("e1", apply) // duplicate -> skipped
	if calls != 1 {
		t.Fatalf("apply ran %d times, want 1", calls)
	}

	failCalls := 0
	fail := func() error { failCalls++; return errors.New("boom") }
	if err := s.Handle("e2", fail); err == nil {
		t.Fatal("expected error propagated")
	}
	// e2 not recorded on failure, so retry runs again
	_ = s.Handle("e2", func() error { failCalls++; return nil })
	if failCalls != 2 {
		t.Fatalf("failCalls=%d, want 2 (retry ran)", failCalls)
	}
}

