package solution

import "hash/fnv"

// PartitionFor deterministically maps a key to a partition index,
// mirroring how a hash balancer pins one key to one partition.
func PartitionFor(key []byte, numPartitions int) int {
	if numPartitions <= 1 {
		return 0
	}
	h := fnv.New32a()
	_, _ = h.Write(key)
	// Mask off the sign bit to stay non-negative, then reduce.
	return int(h.Sum32()&0x7fffffff) % numPartitions
}

