func TestPartitionFor(t *testing.T) {
	if got := PartitionFor([]byte("x"), 1); got != 0 {
		t.Fatalf("numPartitions=1 got %d want 0", got)
	}
	p1 := PartitionFor([]byte("order-1"), 8)
	p2 := PartitionFor([]byte("order-1"), 8)
	if p1 != p2 {
		t.Fatalf("non-deterministic: %d vs %d", p1, p2)
	}
	if p1 < 0 || p1 >= 8 {
		t.Fatalf("out of range: %d", p1)
	}
