func consume(ctx context.Context, r *kafka.Reader) error {
	for {
		m, err := r.FetchMessage(ctx)
		if err != nil {
			return err
		}
		if err := process(m); err != nil { // do the work FIRST
			// on failure: retry / dead-letter, but do NOT commit
			continue
		}
		// commit ONLY after successful processing -> at-least-once
		if err := r.CommitMessages(ctx, m); err != nil {
			return err
		}
	}
}

func RunPool(ctx context.Context, in <-chan []byte, workers int, handle func(context.Context, []byte) error) {
	var wg sync.WaitGroup
	wg.Add(workers)
	for i := 0; i < workers; i++ {
		go func() {
			defer wg.Done()
			for {
				select {
				case <-ctx.Done(): // cancellation: stop pulling work
					return
				case msg, ok := <-in:
					if !ok { // channel closed: no more work
						return
					}
					if err := handle(ctx, msg); err != nil {
						log.Printf("handle error: %v", err)
					}
				}
			}
		}()
	}
	wg.Wait() // block until all workers drain/stop
}

func LowestUncommitted(committed int64, done map[int64]bool) int64 {
	next := committed + 1
	for done[next] { // advance only through a contiguous completed run
		delete(done, next) // no longer needed once folded into committed
		committed = next
		next++
	}
	return committed // highest safe-to-commit offset; a gap stops us
}
